function [allData, scenario, sensor] = intelligentintersection_occlusion_scenario()
%intelligentintersection_occlusion_scenario - Returns sensor detections
%    allData = intelligentintersection_occlusion_scenario returns sensor detections in a structure
%    with time for an internally defined scenario and sensor suite.
%
%    [allData, scenario, sensors] = intelligentintersection_occlusion_scenario optionally returns
%    the drivingScenario and detection generator objects.

% Generated by MATLAB(R) 24.2 (R2024b) and Automated Driving Toolbox 24.2 (R2024b).
% Generated on: 12-Aug-2025 11:10:08

% ================ USER CONFIG ======================
cfg.udpEnable = true;
cfg.udpHost = '127.0.0.1';
cfg.udpPort = 8000;
cfg.payload = 'json';    % json or csv
cfg.selectMode = 'names';
cfg.selectNames = {'Car1', 'RadarCar'};
cfg.selectIDs = [];
cfg.bigEndian = false;
% ===================================================

% Create the drivingScenario object and ego car
[scenario, egoVehicle] = createDrivingScenario;

% Create all the sensor...s
sensor = createSensor(scenario);

% Add sensor to scenario
addSensors(scenario, sensor, egoVehicle.ActorID);


% ===================================================
if cfg.udpEnable
    u = udpport("IPV4", "EnablePortSharing", true);
else
    u = [];
end
% ===================================================

allData = struct('Time', {}, 'ActorPoses', {}, 'ObjectDetections', {}, 'LaneDetections', {}, 'PointClouds', {}, 'INSMeasurements', {});
running = true;
stepIdx = uint32(0);
selector = makeSelector(cfg, scenario);
while running
    stepIdx = stepIdx + 1;
    time  = scenario.SimulationTime;

    if ~isa(sensor,'insSensor')
        poses = targetPoses(scenario,sensor.SensorIndex);
    end
    % Generate detections for the sensor
    laneDetections = [];
    ptClouds = [];
    insMeas = [];
    [objectDetections, isValidTime] = sensor(poses, time);
    numObjects = length(objectDetections);
    objectDetections = objectDetections(1:numObjects);

    % Aggregate all detections into a structure for later use
    if isValidTime
        allData(end + 1) = struct( ...
            'Time',       scenario.SimulationTime, ...
            'ActorPoses', actorPoses(scenario), ...
            'ObjectDetections', {objectDetections}, ...
            'LaneDetections', {laneDetections}, ...
            'PointClouds',   {ptClouds}, ... %#ok<AGROW>
            'INSMeasurements',   {insMeas}); %#ok<AGROW>
    end...
    
% =============== sending block =====================
    if cfg.udpEnable
        poses = actorPoses(scenario);
        for k = 1:numel(poses)
            actIdx = find([scenario.Actors.ActorID] == poses(k).ActorID,1);
            if isempty(actIdx), continue; end
            isVehicle = scenario.Actors(actIdx).ClassID == 1;
            if ~isVehicle, continue; end
            if ~selector(poses(k).ActorID, scenario.Actors(actIdx).Name), continue; end

            vx = poses(k).Velocity(1);  vz = poses(k).Velocity(3);
            speed_mps = hypot(vx, vz);

            switch lower(cfg.payload)
                case 'csv'
                    % step,time,actorID,x,y,z,vx,vy,vz
                    line = sprintf('%u,%.6f,%u,%.3f,%.3f,%.3f,%.3f\n', ...
                    stepIdx, time, poses(k).ActorID, poses(k).Position(1), ...
                    poses(k).Position(2), speed_mps);
                    write(u, uint8(line), cfg.udpHost, cfg.udpPort);

                case 'json'
                msg = struct( ...
                    'ver', 1, 'type', 'vehicle_state', ...
                    'step', stepIdx, 'time', time, 'id', poses(k).ActorID, ...
                    'pos', struct('x',poses(k).Position(1),'y',poses(k).Position(2),'z',poses(k).Position(3)), ...
                    'speed_mps', speed_mps);
                txt = [jsonencode(msg) newline];
                write(u, uint8(txt), cfg.udpHost, cfg.udpPort);

                otherwise
                    % fall back to your current binary
                    payload = packVehicleState(stepIdx, time, poses(k), cfg.bigEndian);
                    write(u, payload, cfg.udpHost, cfg.udpPort);
            end
        end
    end
% ===================================================
    
    % Advance the scenario one time step and exit the loop if the scenario is complete
    running = advance(scenario);
end

% Restart the driving scenario to return the actors to their initial positions.
restart(scenario);

% Release the sensor object so it can be used again.
release(sensor);

% ================ clear UDP ========================
if cfg.udpEnable && ~isempty(u) && isvalid(u)
    clear u;
end
% ===================================================


