% ======================local helpers======================
function selector = makeSelector(cfg, scenario)
switch lower(cfg.selectMode)
    case 'names'
        nameSet = string(cfg.selectNames(:));
        selector = @(id, name) any(strcmpi(string(name), nameSet));
    case 'ids'
        idSet = uint32(cfg.selectIDs(:));
        selector = @(id, ~) any(uint32(id)==idSet);
    otherwise
        selector = @(varargin) false;
end

function payload = packVehicleState(stepIdx, simTime, pose, bigEndian)

buf = uint8([]);
buf = [buf; uint8(1)];          % version
buf = [buf; uint8(1)];          % msgType = vehicle state
buf = [buf; pack(uint32(stepIdx), 'uint32', bigEndian)];
buf = [buf; pack(simTime,        'double', bigEndian)];
buf = [buf; pack(uint32(pose.ActorID), 'uint32', bigEndian)];
buf = [buf; pack(double(pose.Position(:).'), 'double', bigEndian)]; % x y z

vel = pose.Velocity;
if isempty(vel), vel = [NaN NaN NaN]; end
payload = [buf; pack(double(vel(:).'), 'double', bigEndian)];

function out = pack(val, typeName, bigEndian)
% Packs numeric(s) into uint8 with endian control
switch typeName
    case 'uint32'
        bytes = typecast(uint32(val), 'uint8');
    case 'double'
        bytes = typecast(double(val), 'uint8');
    otherwise
        error('Unsupported type');
end
if bigEndian
    % swap within each element size
    elSize = numel(bytes) / numel(val);
    bytes = reshape(bytes, [elSize, numel(val)]);
    bytes = flipud(bytes);
    bytes = bytes(:);
end
out = bytes(:);
